/* ChartPulse — Global Styles */

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16162a;
  --bg-card: #1e1e32;
  --bg-hover: #252540;
  --border-color: #2a2a45;
  --text-primary: #e8e8f0;
  --text-secondary: #a0a0b8;
  --text-muted: #6b6b8a;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd8;
  --green: #22c55e;
  --green-dim: #16a34a;
  --red: #F7525F;
  --red-dim: #dc2626;
  --yellow: #f59e0b;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

ul, ol {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--bg-primary);
}
::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Utility classes */
.text-green { color: var(--green); }
.text-red { color: var(--red); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

.bg-green { background: rgba(34,197,94,0.15); }
.bg-red { background: rgba(247,82,95,0.15); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-green { background: rgba(34,197,94,0.15); color: var(--green); }
.badge-red { background: rgba(247,82,95,0.15); color: var(--red); }
.badge-blue { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.badge-gold { background: rgba(245,158,11,0.15); color: var(--yellow); }
.badge-platinum { background: rgba(168,162,158,0.15); color: #a8a2a2; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 0.15s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent-blue);
  color: #fff;
}
.btn-primary:hover {
  background: var(--accent-blue-hover);
}
.btn-secondary {
  background: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover {
  background: var(--bg-hover);
}
.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}
.btn-ghost:hover {
  color: var(--text-primary);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
}
.tab {
  padding: 10px 16px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: all 0.15s;
}
.tab:hover {
  color: var(--text-primary);
}
.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
}
.card-header {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.card-title {
  font-size: 0.95rem;
  font-weight: 600;
}
.card-body {
  padding: 14px 18px;
}

/* Tables */
.table-wrap {
  overflow-x: auto;
}
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}
th, td {
  padding: 10px 14px;
  text-align: left;
  white-space: nowrap;
}
th {
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
tbody tr {
  border-top: 1px solid var(--border-color);
  transition: background 0.1s;
}
tbody tr:hover {
  background: var(--bg-hover);
}

/* Sparkline */
.sparkline {
  width: 80px;
  height: 28px;
}

/* Layout */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header / Nav */
.site-header {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}
.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
}
.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-blue);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  color: #fff;
}
.main-nav {
  display: flex;
  gap: 6px;
}
.main-nav a {
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all 0.15s;
}
.main-nav a:hover, .main-nav a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.search-btn {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
}
.search-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* Footer */
.site-footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.footer-col a {
  display: block;
  font-size: 0.8rem;
  color: var(--text-muted);
  padding: 4px 0;
  transition: color 0.15s;
}
.footer-col a:hover {
  color: var(--text-primary);
}
.footer-bottom {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 768px) {
  .main-nav { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

// ChartPulse — Main JavaScript

// Tab switching helper
function initTabs(containerSelector, tabSelector, panelSelector, callback) {
  const containers = document.querySelectorAll(containerSelector);
  containers.forEach(container => {
    const tabs = container.querySelectorAll(tabSelector);
    const panels = container.querySelectorAll(panelSelector);
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        const target = tab.dataset.tab;
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        panels.forEach(p => {
          p.classList.toggle('hidden', p.dataset.panel !== target);
        });
        if (callback) callback(target);
      });
    });
  });
}

// Accordion helper
function initAccordions(selector) {
  document.querySelectorAll(selector).forEach(header => {
    header.addEventListener('click', () => {
      const body = header.nextElementSibling;
      const icon = header.querySelector('.accordion-icon');
      const isOpen = body.style.display !== 'none' && body.style.display !== '';
      body.style.display = isOpen ? 'none' : 'block';
      if (icon) icon.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
    });
  });
}

// Mobile nav toggle
function initMobileNav() {
  const toggle = document.querySelector('.mobile-nav-toggle');
  const nav = document.querySelector('.main-nav');
  if (toggle && nav) {
    toggle.addEventListener('click', () => {
      nav.classList.toggle('mobile-open');
    });
  }
}

// Sparkline SVG generator
function generateSparkline(data, width, height, color) {
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const stepX = width / (data.length - 1);
  let path = `M0,${height - ((data[0] - min) / range) * height}`;
  for (let i = 1; i < data.length; i++) {
    const x = i * stepX;
    const y = height - ((data[i] - min) / range) * height;
    path += ` L${x},${y}`;
  }
  return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><path d="${path}" fill="none" stroke="${color}" stroke-width="1.5"/></svg>`;
}

// Render sparklines on page
function renderSparklines() {
  document.querySelectorAll('[data-sparkline]').forEach(el => {
    const data = JSON.parse(el.dataset.sparkline);
    const color = el.dataset.color || '#22c55e';
    el.innerHTML = generateSparkline(data, 80, 28, color);
  });
}

// Candlestick chart canvas renderer
function renderCandlestickChart(canvasId, data, timeframe) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);
  const w = rect.width;
  const h = rect.height;

  ctx.clearRect(0, 0, w, h);

  // Grid
  ctx.strokeStyle = '#2a2a45';
  ctx.lineWidth = 0.5;
  for (let i = 0; i <= 4; i++) {
    const y = (h / 4) * i;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(w, y);
    ctx.stroke();
  }

  if (!data || data.length === 0) return;

  const candleW = Math.max(2, (w / data.length) * 0.6);
  const gap = w / data.length;
  const allPrices = data.flatMap(d => [d.high, d.low]);
  const minP = Math.min(...allPrices);
  const maxP = Math.max(...allPrices);
  const range = maxP - minP || 1;
  const pad = 20;
  const chartH = h - pad * 2;

  const priceToY = p => pad + chartH - ((p - minP) / range) * chartH;

  data.forEach((c, i) => {
    const x = i * gap + gap / 2;
    const isGreen = c.close >= c.open;
    ctx.fillStyle = isGreen ? '#22c55e' : '#F7525F';
    ctx.strokeStyle = isGreen ? '#22c55e' : '#F7525F';

    // Wick
    ctx.beginPath();
    ctx.moveTo(x, priceToY(c.high));
    ctx.lineTo(x, priceToY(c.low));
    ctx.stroke();

    // Body
    const bodyTop = priceToY(Math.max(c.open, c.close));
    const bodyBottom = priceToY(Math.min(c.open, c.close));
    const bodyH = Math.max(1, bodyBottom - bodyTop);
    ctx.fillRect(x - candleW / 2, bodyTop, candleW, bodyH);
  });

  // Price labels on right
  ctx.fillStyle = '#6b6b8a';
  ctx.font = '10px Inter, sans-serif';
  ctx.textAlign = 'left';
  for (let i = 0; i <= 4; i++) {
    const price = minP + (range * (1 - i / 4));
    ctx.fillText(price.toFixed(2), w - 50, (h / 4) * i + 10);
  }
}

// Generate sample candlestick data
function generateCandleData(count, basePrice, volatility) {
  const data = [];
  let price = basePrice;
  for (let i = 0; i < count; i++) {
    const open = price;
    const change = (Math.random() - 0.48) * volatility;
    const close = open + change;
    const high = Math.max(open, close) + Math.random() * volatility * 0.5;
    const low = Math.min(open, close) - Math.random() * volatility * 0.5;
    data.push({ open, high, low, close });
    price = close;
  }
  return data;
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
  initMobileNav();
  renderSparklines();

  // Chart page init
  const chartCanvas = document.getElementById('candlestickCanvas');
  if (chartCanvas) {
    let tf = '1D';
    let data = generateCandleData(60, 263, 4);
    const draw = () => renderCandlestickChart('candlestickCanvas', data, tf);
    draw();
    window.addEventListener('resize', draw);

    document.querySelectorAll('.tf-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.tf-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        tf = btn.dataset.tf;
        const counts = { '1D': 60, '5D': 100, '1M': 80, '3M': 90, '6M': 120, 'YTD': 150, '1Y': 200, '5Y': 250, 'All': 300 };
        data = generateCandleData(counts[tf] || 60, 263, tf === '1D' ? 4 : tf === '5Y' ? 15 : 8);
        draw();
      });
    });
  }
});

